// Benchmark: nondet_safe.c
// Expected: TRUE (assertion is unreachable for all inputs)
// Suitable for: predicate abstraction / CEGAR
// Invariant: x + y == n always holds
extern unsigned __VERIFIER_nondet_uint();
extern void __assert_fail(const char *assertion, const char *file,
                          unsigned int line, const char *function);
int main() {
  unsigned n = __VERIFIER_nondet_uint();
  unsigned x = __VERIFIER_nondet_uint();
  unsigned y = n - x;
  while (x > y) {
    x--;
    y++;
    if (x + y != n) {
      __assert_fail("invariant", "nondet_safe.c", 15, "main");
    }
  }
  return 0;
}
// Benchmark: nondet_unsafe.c
// Expected: FALSE (assertion is reachable for some inputs)
// Suitable for: predicate abstraction / CEGAR
extern unsigned __VERIFIER_nondet_uint();
extern void __assert_fail(const char *assertion, const char *file,
                          unsigned int line, const char *function);
int main() {
  unsigned n = __VERIFIER_nondet_uint();
  unsigned x = __VERIFIER_nondet_uint();
  unsigned y = n - x;
  while (x > y) {
    x--;
    y++;
    if (x < y) {
      __assert_fail("no_cross", "nondet_unsafe.c", 15, "main");
    }
  }
  return 0;
}

